// src/hooks/UseNotifications.js
import { useCallback, useEffect, useState } from 'react';
import {
  fetchNotifications,
  fetchNotificationById,
  fetchNotificationStats,
} from '../api/NotificationsApi';

export function useNotifications(initialLimit = 100) {
  const [notifications, setNotifications] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  // 기존 호환: limit
  const [limit, setLimit] = useState(initialLimit);

  // 확장: page / filters
  const [page, setPage] = useState(1);
  const [filters, setFilters] = useState({
    keyword: '',
    level: '',
    from: '',
    to: '',
  });

  const refresh = useCallback(async () => {
    try {
      setLoading(true);
      setError(null);

      const res = await fetchNotifications({
        page,
        size: limit,
        from: filters.from,
        to: filters.to,
        level: filters.level,
        keyword: filters.keyword,
      });

      // /alerts는 {items,total,...} 형태일 수 있고, fallback은 배열일 수 있음
      const items = Array.isArray(res) ? res : res?.items || [];
      setNotifications(items);
    } catch (e) {
      setError(e);
    } finally {
      setLoading(false);
    }
  }, [page, limit, filters]);

  useEffect(() => {
    refresh();
  }, [refresh]);

  // 상세/통계도 필요하면 같이 노출(페이지에서 선택 사용)
  const getById = useCallback(async (id) => fetchNotificationById(id), []);
  const getStats = useCallback(async (args) => fetchNotificationStats(args), []);

  return {
    notifications,
    loading,
    error,

    limit,
    setLimit,

    page,
    setPage,

    filters,
    setFilters,

    refresh,

    getById,
    getStats,
  };
}
